// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    Attacker attacker;
    LogFile lf;

    function setUp() public {
        c = new PENNY_BY_PENNY();
        lf = new LogFile();
        // set LogFile before Initialized() guarded check
        c.SetLogFile(address(lf));
        // set MinSum to a small value
        c.SetMinSum(1);
        // mark initialized so further Set* cannot be called (match reference usage)
        c.Initialized();
        // deploy attacker which can reenter
        attacker = new Attacker(c);
    }

    // fuzzed: withdrawal amount and initial deposit amount
    function testFuzz_property(uint96 depositAmount, uint96 withdrawAmount) public {
        // keep values reasonable and nonzero so actions have effect
        uint256 dep = uint256(bound(depositAmount, 1, type(uint96).max));
        uint256 wit = uint256(bound(withdrawAmount, 1, type(uint96).max));

        // fund attacker EOA so it can call with value
        address atkEOA = attacker.addr();
        vm.deal(atkEOA, dep * 3 + 1 ether);

        // attacker will put 'dep' into its account with 0 lock so it can collect after
        vm.prank(atkEOA);
        c.Put{value: dep}(0);

        // record pre-balance stored in contract for attacker
        (uint preUnlock, uint preBal) = c.Acc(atkEOA);

        // Ensure preconditions to reach Collect body on reference: balance>=MinSum and balance>=_am and timestamp>unlockTime
        // advance time past unlock
        vm.warp(block.timestamp + 1);

        // Now attempt Collect through attacker which will try to reenter once during the low-level call
        // We must observe whether the call completed (ok) or reverted on the reference. The reference may revert or succeed depending on inputs.
        bool ok;
        // attacker will attempt to collect 'wit'
        vm.prank(atkEOA);
        try c.Collect{value: 0}(wit) {
            ok = true;
        } catch {
            ok = false;
        }

        // Observe post state: read attacker's recorded contract balance
        (uint postUnlock, uint postBal) = c.Acc(atkEOA);

        // General rule (assert): If the Collect call completed successfully (ok==true) on the reference, then the recorded balance decreased by AT MOST the requested amount.
        // This is a universal property: for the correct contract, whenever Collect returns (does not revert), acc.balance >= preBal - wit.
        // The mutant allowing reentrancy can make the attacker drain more than 'wit' in one Collect call, violating this.
        if (ok) {
            // enforce the invariant on the observable getter
            assertTrue(postBal + wit >= preBal);
        } else {
            // if Collect reverted on reference, that's acceptable; just assert that state unchanged (defensive)
            // ensure no unexpected negative change recorded when call reverted
            assertTrue(postBal == preBal);
        }
    }
}

// Attacker contract: on receive it will try to reenter Collect exactly once to simulate reentrancy that the mutant allows.
contract Attacker {
    PENNY_BY_PENNY public c;
    bool private entered;
    address private owner;

    constructor(PENNY_BY_PENNY _c) {
        c = _c;
        owner = msg.sender;
    }

    function addr() external view returns (address) { return address(this); }

    // fallback/receive will try a single reentrant Collect call (reentrancy guard in reference prevents it)
    receive() external payable {
        if (!entered) {
            entered = true;
            // attempt to reenter withdrawing a small amount (1 wei) to cause extra drain if allowed
            // Use try/catch to avoid bubbling revert into original call; mutant may allow success leading to extra drain
            try c.Collect{value:0}(1) {
                // ignore result
            } catch {
                // ignore
            }
        }
    }
}
